import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
};

const ALL_STATUSES: ProjectStatus[] = ['active', 'paused', 'over'];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Витрина каталога', used: 420, quota: 1000, status: 'active' },
  { id: 'p2', name: 'Платёжный шлюз', used: 980, quota: 1000, status: 'over' },
  { id: 'p3', name: 'Мобильный клиент', used: 310, quota: 800, status: 'active' },
  { id: 'p4', name: 'Аналитика событий', used: 640, quota: 900, status: 'paused' },
  { id: 'p5', name: 'Поиск по документам', used: 120, quota: 500, status: 'active' },
  { id: 'p6', name: 'Импорт из CRM', used: 700, quota: 700, status: 'over' },
  { id: 'p7', name: 'Уведомления', used: 210, quota: 600, status: 'paused' },
  { id: 'p8', name: 'Личный кабинет', used: 455, quota: 1000, status: 'active' },
  { id: 'p9', name: 'Отчёты для бухгалтерии', used: 890, quota: 1200, status: 'active' },
  { id: 'p10', name: 'Онбординг', used: 150, quota: 400, status: 'paused' },
  { id: 'p11', name: 'Партнёрский API', used: 1100, quota: 1000, status: 'over' },
  { id: 'p12', name: 'Внутренние инструменты', used: 260, quota: 900, status: 'active' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [filters, setFilters] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => filters.includes(project.status)),
    [filters],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const rows = visible.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setFilters((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setFilters(ALL_STATUSES);
    setPage(1);
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {ALL_STATUSES.map((status) => {
          const selected = filters.includes(status);
          return (
            <JxChip
              key={status}
              active={selected}
              removable={selected}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {rows.length === 0 ? (
        <JxEmptyState
          title="Проектов не найдено"
          message="Ни один проект не подходит под выбранные фильтры статуса."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {rows.map((project) => {
              const meta = STATUS_META[project.status];
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <span style={{ flex: 1, minWidth: 0, color: 'var(--jx-text)' }}>{project.name}</span>
                  <span style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-mono)' }}>
                    {project.used} / {project.quota}
                  </span>
                  <JxProgressCircle value={project.used} max={project.quota} showValue />
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

